.version 8.2
.target sm_89
.address_size 64
// Optimization: register blocking over the reduction (kernel-column) axis.
// The inner accumulation loop now processes two adjacent kernel columns
// (kx, kx+1) per iteration with strength-reduced addressing: the shared-
// memory input address and the global weight address live in registers and
// advance by constant byte increments instead of being recomputed with
// mul/shl/cvt chains for every tap. Each inner iteration now issues 4 FMAs
// per ~15 instructions (was 2 FMAs per ~16), roughly halving the non-FMA
// instruction overhead that dominates this compute-throughput-bound kernel.
// Thread/CTA mapping, 16x16x2 output tiling, shared-memory halo staging,
// occupancy, and per-element accumulation order are all unchanged.
.visible .entry conv2d_3x96_k11_s4_p2(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elems
)
