    add.u32 %r_addr, %r_addr, %r_sin;
    st.shared.f32 [%r_addr], %f_a;
    add.u32 %r_idx, %r_idx, 256;
    bra L_stage;
L_stage_done:
    bar.sync 0;
    // per-channel base addresses for the accumulation loops
    mov.u32 %r_saddr, %r_sbase;
    mul.lo.u32 %r_tmp2, %r_ic, 121;
    add.u32 %r_tmp2, %r_tmp2, %r_wbase;
    cvt.u64.u32 %rd_waddr, %r_tmp2;
    shl.b64 %rd_waddr, %rd_waddr, 2;
    add.u64 %rd_waddr, %rd_waddr, %rd_wt;
    // accumulate 11x11 from shared tile into two output accumulators.
    // register-blocked over kx: two taps per iteration, incremental
    // byte-address updates, odd tap (kx=10) handled as an explicit tail.
    mov.u32 %r_ky, 0;
L_ky:
    setp.ge.u32 %p, %r_ky, 11;
    @%p bra L_ky_done;
    mov.u32 %r_kx, 0;
L_kx:
    // taps (ky,kx) and (ky,kx+1)
    ld.shared.f32 %f_a0, [%r_saddr];
    ld.shared.f32 %f_a1, [%r_saddr+4];
    ld.global.f32 %f_b0, [%rd_waddr];
    ld.global.f32 %f_b1, [%rd_waddr+1452];
    ld.global.f32 %f_b2, [%rd_waddr+4];
    ld.global.f32 %f_b3, [%rd_waddr+1456];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    fma.rn.f32 %f_acc0, %f_a1, %f_b2, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a1, %f_b3, %f_acc1;
    add.u32 %r_saddr, %r_saddr, 8;
    add.u64 %rd_waddr, %rd_waddr, 8;
    add.u32 %r_kx, %r_kx, 2;
    setp.lt.u32 %p, %r_kx, 10;
    @%p bra L_kx;
