    ld.shared.f32 %f_a0, [%r_saddr];
    ld.global.f32 %f_b0, [%rd_waddr];
    ld.global.f32 %f_b1, [%rd_waddr+1452];
    fma.rn.f32 %f_acc0, %f_a0, %f_b0, %f_acc0;
    fma.rn.f32 %f_acc1, %f_a0, %f_b1, %f_acc1;
    // advance addresses to tap (ky+1,0): +61 halo elements / +1 weight float
    add.u32 %r_saddr, %r_saddr, 244;
    add.u64 %rd_waddr, %rd_waddr, 4;
    add.u32 %r_ky, %r_ky, 1;
    bra L_ky;
